  "第 {n} 天 / 共 {total} 天": "Ngày {n} / tổng {total} ngày",
  "聽{name}唸": "Nghe {name} đọc",
  "今天:{done}/{total} 完成": "Hôm nay: {done}/{total} hoàn thành",
